recipes.code:
{
  "inputs": [
    {
      "id": "mcp-api-token",
      "type": "promptString",
      "description": "API key (pz_...) or JWT token from PingZen (omit for test mode)",
      "password": true
    },
    {
      "id": "database-url",
      "type": "promptString",
      "description": "PostgreSQL connection string",
      "password": true
    },
    {
      "id": "secret-key",
      "type": "promptString",
      "description": "JWT signing secret",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "docker",
      "args": [
        "run",
        "-i",
        "--rm",
        "docker.io/ilyakong/pingzen-mcp:0.9.3"
      ],
      "env": {
        "MCP_API_TOKEN": "${input:mcp-api-token}",
        "DATABASE_URL": "${input:database-url}",
        "SECRET_KEY": "${input:secret-key}"
      }
    }
  }
}
